let language=localStorage.getItem('lavender-estate-language')||'ru',fallback,config,inviteId,observer;
const localeCode=()=>language==='ky'?'ky-KG':language==='kk'?'kk-KZ':'ru-RU';

async function load(){
 fallback=await fetch('/content.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('fallback');return r.json()});
 inviteId=invitationIdFromPath(location.pathname,fallback.backend.defaultId)||String(fallback.backend.defaultId);
 try{const r=await fetch(`${fallback.backend.baseUrl}/${inviteId}`,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error(r.status);config=adaptXanoInvitation(await r.json(),fallback)}catch(error){console.warn('Using invitation fallback',error);config=fallback}
 const enabled=config.enabledLanguages||['ru','ky'];if(!enabled.includes(language))language=config.defaultLanguage||enabled[0];
 const switcher=$('.language-menu');$$('[data-lang]',switcher).forEach(b=>b.hidden=!enabled.includes(b.dataset.lang));switcher.hidden=enabled.length<2;render();
}
function render(){
 const text=dictionary[language],content=config.locales[language]||config.locales.ru,dateInfo=getDateInfo();
 document.documentElement.lang=language;document.body.classList.toggle('lang-ky',language!=='ru');
 $$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===language));$('.language-menu__current').textContent=language==='ky'?'KG':language==='kk'?'KZ':'RU';$$('[data-i18n]').forEach(el=>{if(text[el.dataset.i18n])el.textContent=text[el.dataset.i18n]});
 $$('[data-name="first"]').forEach(el=>el.textContent=config.names.first);$$('[data-name="second"]').forEach(el=>el.textContent=config.names.second);
 $('[data-initial="first"]').textContent=[...config.names.first][0]||'';$('[data-initial="second"]').textContent=[...config.names.second][0]||'';
 $('[data-content="welcomeTitle"]').textContent=content.welcomeTitle||'';$('[data-content="welcome"]').textContent=content.welcome||'';
 $$('[data-venue]').forEach(el=>el.textContent=content.venue[el.dataset.venue]||'');$$('[data-date="long"]').forEach(el=>el.textContent=dateInfo.long);
 $('[data-date="monthYear"]').textContent=`${text.months[dateInfo.month-1]} ${dateInfo.year}`;$('[data-date="weekday"]').textContent=dateInfo.weekday;$('[data-date="time"]').textContent=dateInfo.time;$('[data-date="short"]').textContent=`${String(dateInfo.day).padStart(2,'0')} · ${String(dateInfo.month).padStart(2,'0')} · ${dateInfo.year}`;
 renderCalendar(dateInfo);renderSchedule(content.schedule||[]);updateCountdown();updateMetadata(dateInfo.long);
 const query=[content.venue.name,content.venue.address].filter(Boolean).join(', '),google=validMapUrl(config.map?.googleUrl)||(query?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`:''),twoGis=validMapUrl(config.map?.twoGisUrl)||(query?`https://2gis.kg/search/${encodeURIComponent(query)}`:'');const mapBox=$('.map-buttons');mapBox.hidden=!(google||twoGis);$('#googleMapLink').hidden=!google;$('#twoGisLink').hidden=!twoGis;$('#googleMapLink').href=google||'#';$('#twoGisLink').href=twoGis||'#';
 const wish=$('#wishBlock');wish.hidden=!config.wishBlock?.enabled;if(!wish.hidden){$('#wishBlockTitle').textContent=content.wishTitle;$('#wishBlockText').textContent=content.wishText}
 $('#rsvp').hidden=config.rsvp?.enabled===false;$('#guestWishField').hidden=config.rsvp?.allowGuestWish===false;configureGuestCount();observeReveals();
}
function getDateInfo(){const [year,month,day]=config.date.slice(0,10).split('-').map(Number),date=new Date(config.date);return{year,month,day,long:date.toLocaleDateString(localeCode(),{day:'numeric',month:'long',year:'numeric',timeZone:config.timezone}),weekday:date.toLocaleDateString(localeCode(),{weekday:'long',timeZone:config.timezone}),time:date.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:config.timezone})}}
function renderCalendar(info){const holder=$('#calendar'),first=(new Date(info.year,info.month-1,1).getDay()+6)%7,days=new Date(info.year,info.month,0).getDate();holder.replaceChildren();dictionary[language].week.forEach(x=>holder.insertAdjacentHTML('beforeend',`<span class="weekday">${x}</span>`));for(let i=0;i<first;i++)holder.insertAdjacentHTML('beforeend','<span class="empty">0</span>');for(let day=1;day<=days;day++)holder.insertAdjacentHTML('beforeend',`<span${day===info.day?' class="wedding-day"':''}>${day}</span>`)}
function renderSchedule(items){const icons=['welcome','rings','dinner','music','stars'];$('#schedule').innerHTML=items.map((item,index)=>`<article class="program-item reveal"><time>${escapeHtml(item.time)}</time><svg class="program-item__icon" aria-hidden="true"><use href="assets/program-icons.svg#${icons[index%icons.length]}"></use></svg><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.description)}</p></div></article>`).join('')}
function configureGuestCount(){const select=$('[name="guests_count"]'),max=config.rsvp?.maxGuests||10;select.replaceChildren(...Array.from({length:max},(_,i)=>Object.assign(document.createElement('option'),{value:String(i+1),textContent:String(i+1)})))}
function updateCountdown(){if(!config)return;const left=Math.max(0,new Date(config.date)-Date.now()),values={days:Math.floor(left/86400000),hours:Math.floor(left/3600000)%24,minutes:Math.floor(left/60000)%60};$$('[data-count]').forEach(el=>el.textContent=el.dataset.count==='days'?String(values.days).padStart(3,'0'):String(values[el.dataset.count]).padStart(2,'0'))}
function updateMetadata(date){const title=`${config.names.first} & ${config.names.second} — ${dictionary[language].invitation}`,description=`${date}. ${config.locales[language].venue.name}`;document.title=title;$('meta[name="description"]').content=description;$('meta[property="og:title"]').content=title;$('meta[property="og:description"]').content=description}
function escapeHtml(value=''){const node=document.createElement('div');node.textContent=String(value);return node.innerHTML}
function observeReveals(){observer?.disconnect();observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('.reveal:not(.is-visible)').forEach(el=>observer.observe(el))}

const languageMenu=$('.language-menu'),languageMenuToggle=$('.language-menu__toggle');
languageMenuToggle.addEventListener('click',()=>{const open=languageMenu.classList.toggle('is-open');languageMenuToggle.setAttribute('aria-expanded',String(open))});
document.addEventListener('click',event=>{if(!languageMenu.contains(event.target)){languageMenu.classList.remove('is-open');languageMenuToggle.setAttribute('aria-expanded','false')}});
$$('[data-lang]').forEach(button=>button.addEventListener('click',()=>{if(language!==button.dataset.lang){language=button.dataset.lang;localStorage.setItem('lavender-estate-language',language);if(config)render()}languageMenu.classList.remove('is-open');languageMenuToggle.setAttribute('aria-expanded','false')}));
$('#rsvpForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=$('button[type="submit"]',form),status=$('#formStatus'),values=new FormData(form),guest={name:String(values.get('name')||'').trim(),wish:String(values.get('wish')||'').trim(),guests_count:Number(values.get('guests_count')),is_attending:values.get('attending')==='yes'};if(!guest.name)return;button.disabled=true;$('span',button).textContent=dictionary[language].sending;status.textContent='';try{const base=config.backend?.baseUrl||fallback.backend.baseUrl,fresh=await fetch(`${base}/${inviteId}`,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('read');return r.json()}),payload=createGuestPatch(fresh,inviteId,guest),response=await fetch(`${base}/${inviteId}/full`,{method:'PATCH',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw Error(response.status);config=adaptXanoInvitation(payload,fallback);form.reset();status.textContent=dictionary[language].sent}catch(error){console.error(error);status.textContent=dictionary[language].sendError}finally{button.disabled=false;$('span',button).textContent=dictionary[language].send}});
$('#calendarButton').addEventListener('click',()=>{const content=config.locales[language],start=new Date(config.date),end=new Date(config.endDate||start.getTime()+21600000),stamp=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const ics=['BEGIN:VCALENDAR','VERSION:2.0','BEGIN:VEVENT',`DTSTART:${stamp(start)}`,`DTEND:${stamp(end)}`,`SUMMARY:${config.names.first} & ${config.names.second}`,`LOCATION:${String(content.venue.address).replaceAll(',','\\,')}`,'END:VEVENT','END:VCALENDAR'].join('\r\n'),url=URL.createObjectURL(new Blob([ics],{type:'text/calendar'})),link=document.createElement('a');link.href=url;link.download='wedding.ics';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{document.documentElement.style.setProperty('--scroll-y',String(scrollY));ticking=false})},{passive:true});
load();setInterval(updateCountdown,30000);
